"""Low level interaction functions for reconstruction window"""

import squishtest
from interops.libraries.squish_actions import common
from interops.libraries.xvi.interactions.objects.xvi_objects import Xvi_MainPage
from interops.libraries.xvi.xvi_types import Reconstruction_Preset
from interops.libraries.miscellaneous.decorators import log_decorator
from interops.libraries.xvi.interactions.common_objects_ops import get_text,click_item

class ReconstructionWindowOps:
    '''
    Reconstruction window handler
    '''
    def __init__(self):
        squishtest.waitForObjectExists(Xvi_MainPage.reconstruction_Preset_Selection_Dialog)

    @property
    def preset_type(self):
        self._preset_type = get_text(Xvi_MainPage.preset_Type_ComboBox)
        return self._preset_type

    @preset_type.setter
    def preset_type(self, value):
        click_item(Xvi_MainPage.preset_Type_ComboBox, value)
        self._preset_type = value

    @property
    def preset(self):
        self._preset = get_text(Xvi_MainPage.preset_ComboBox)
        return self._preset

    @preset.setter
    def preset(self, value):
        click_item(Xvi_MainPage.preset_ComboBox, value)
        self._preset = value

    @property
    def description(self):
        self._description= get_text(Xvi_MainPage.reconstruction_Preset_Selection_Description_Edit)
        return self._description

    @log_decorator
    def click_OK_button(self):
        common.left_click_object(Xvi_MainPage.reconstruction_Preset_Selection_OK_Button)

    @log_decorator
    def click_Cancel_button(self):
        common.left_click_object(Xvi_MainPage.reconstruction_Preset_Selection_Cancel_Button)

@log_decorator
def collectReconstructionPreset():
    rec = Reconstruction_Preset()
    rec_ops = ReconstructionWindowOps()
    rec.preset_type = rec_ops.preset_type
    rec.preset = rec_ops.preset
    rec.description = rec_ops.description
    return rec, rec_ops

@log_decorator
def setReconstructionPreset(rec: Reconstruction_Preset):
    rec_ops = ReconstructionWindowOps()
    rec_ops.preset_type = rec.preset_type
    rec_ops.preset = rec.preset
    return rec_ops
